"""Evaluates every claim in every session and writes the claim report and paper numbers.

Outputs <out>/{claims.md, claims.csv, claims.json} (default
data/derived/reports/confirm-<stamp>/) and paper/generated/numbers.tex: LaTeX
macros with the cross-session median (and min / max) of each headline value and
each claim's verdict, so the paper never carries hand-copied numbers.
"""

# ruff: noqa: E501 - table-building lines are kept verbatim from the original script
# The first line of numbers.tex ("% Generated by benchmarks/analysis/confirm_claims.py") is kept verbatim: it is
# part of the pinned baseline (docs/verification/baseline/numbers.normalized.tex).

from __future__ import annotations

import csv
import datetime as dt
import json
from pathlib import Path

import numpy as np

from .. import paths
from ..io import excluded_runs, label, load_sessions
from ..units import fmt_compact as fmt
from . import definitions  # noqa: F401 - registers the claims
from .registry import CLAIMS, Missing


def _shown(path: Path) -> Path:
    """`path` relative to the repository when inside it, else as given."""
    try:
        return path.relative_to(paths.REPO)
    except ValueError:
        return path


def run_claims(allow_dirty: bool = False, out_dir: Path | None = None, data_dir: Path | None = None,
               numbers_path: Path | None = None) -> int:
    """Evaluates all claims in all sessions and writes the claim report and the paper numbers.

    Args:
        allow_dirty: include runs from uncommitted (`-dirty`) builds.
        out_dir: report directory (default `data/derived/reports/confirm-<stamp>/`).
        data_dir: data tree to read (default the repository's `data/`).
        numbers_path: LaTeX macro file to write (default `paper/generated/numbers.tex`).

    Returns:
        Process exit code (0).
    """
    data = data_dir or paths.DATA
    numbers = numbers_path or paths.PAPER_NUMBERS
    sessions = load_sessions(allow_dirty, data)

    results = {}  # claim id -> session name -> (values, passed, note) or None
    for c in CLAIMS:
        results[c.id] = {}
        for s in sessions:
            try:
                results[c.id][s.name] = c.fn(s)
            except Missing:
                results[c.id][s.name] = None

    out = out_dir or paths.DERIVED / "reports" / f"confirm-{dt.datetime.now().strftime('%Y%m%d-%H%M%S')}"
    out.mkdir(parents=True, exist_ok=out_dir is not None)
    md = ["# Claim confirmation across sessions", "",
          f"{len(sessions)} session(s): " + ", ".join(f"`{label(s)}` = `{s.name}`" for s in sessions) + ".",
          "Criteria are fixed in `python/computeedge_analysis/claims/definitions.py`. A claim is paper-ready when it is "
          "**confirmed in >= 3 sessions**. Runs in `data/exclusions.json` are left out "
          f"({len(excluded_runs(data))} excluded).", "",
          "| claim | finding | statement | criterion | " + " | ".join(label(x) for x in sessions)
          + " | verdict |", "|---|---:|---|---|" + "---|" * len(sessions) + "---|"]
    rows_csv, verdicts, json_out, macros_verdict = [], {}, {}, []
    for c in CLAIMS:
        cells, outcomes = [], []
        for s in sessions:
            r = results[c.id][s.name]
            if r is None:
                cells.append("n/a")
                continue
            v, ok, note = r
            outcomes.append(ok)
            key = next(iter(c.headline), next(iter(v)))
            cells.append(("✅ " if ok else "❌ ") + fmt(v[key]))
            for k, val in v.items():
                rows_csv.append([c.id, s.name, k, val, ok])
        n_ok = sum(outcomes)
        if not outcomes:
            verdict = "no data"
        elif n_ok == len(outcomes):
            verdict = f"confirmed ({n_ok}/{len(outcomes)})"
        elif n_ok == 0:
            verdict = f"refuted (0/{len(outcomes)})"
        else:
            verdict = f"inconsistent ({n_ok}/{len(outcomes)})"
        verdicts[c.id] = verdict
        # \verdictof{C1} in the paper (digits are not allowed in LaTeX command names)
        macros_verdict.append(f"\\expandafter\\newcommand\\csname verdict{c.id}\\endcsname{{{verdict}}}")
        md.append(f"| {c.id} | {c.finding} | {c.text} | {c.criterion} | " + " | ".join(cells) + f" | **{verdict}** |")
        json_out[c.id] = {"finding": c.finding, "text": c.text, "criterion": c.criterion, "verdict": verdict,
                          "sessions": {s.name: (None if results[c.id][s.name] is None else
                                                {"values": results[c.id][s.name][0],
                                                 "passed": results[c.id][s.name][1]}) for s in sessions}}

    # Cross-session spread of headline values.
    md += ["", "## Headline values across sessions", "",
           "| claim | value | " + " | ".join(label(x) for x in sessions) + " | median | spread (max/min) |",
           "|---|---|" + "---:|" * len(sessions) + "---:|---:|"]
    macros = []
    for c in CLAIMS:
        for key, macro in c.headline.items():
            vals = []
            cells = []
            for s in sessions:
                r = results[c.id][s.name]
                x = r[0].get(key) if r else None
                cells.append(fmt(x) if isinstance(x, int | float) else "—")
                if c.headline_if and r and not c.headline_if(r[0]):
                    continue
                if isinstance(x, int | float) and x == x:
                    vals.append(float(x))
            if not vals:
                continue
            med = float(np.median(vals))
            spread = (max(vals) / min(vals)) if min(vals) > 0 else float("nan")
            md.append(f"| {c.id} | {key} | " + " | ".join(cells) + f" | {fmt(med)} | {fmt(spread)} |")
            digits = 0 if abs(med) >= 100 else (1 if abs(med) >= 10 else 2)
            macros.append(f"\\newcommand{{\\{macro}}}{{{med:,.{digits}f}}}  % {c.id} {key}, median of {len(vals)} "
                          f"session(s)")
            for suffix, x in (("Min", min(vals)), ("Max", max(vals))):
                d = 0 if abs(x) >= 100 else (1 if abs(x) >= 10 else 2)
                macros.append(f"\\newcommand{{\\{macro}{suffix}}}{{{x:,.{d}f}}}")
    (out / "claims.md").write_text("\n".join(md) + "\n")
    with open(out / "claims.csv", "w", newline="") as f:
        w = csv.writer(f, lineterminator="\n")
        w.writerow(["claim", "session", "value", "x", "passed"])
        w.writerows(rows_csv)
    (out / "claims.json").write_text(json.dumps(json_out, indent=2, default=str) + "\n")

    numbers.parent.mkdir(parents=True, exist_ok=True)
    numbers.write_text(
        "% Generated by benchmarks/analysis/confirm_claims.py -- do not edit.\n"
        f"% Source: {_shown(out)}; {len(sessions)} session(s).\n"
        f"\\newcommand{{\\NumSessions}}{{{len(sessions)}}}\n"
        "\\newcommand{\\verdictof}[1]{\\csname verdict#1\\endcsname}\n" + "\n".join(macros + macros_verdict) + "\n")

    for c in CLAIMS:
        print(f"{c.id:4s} {verdicts[c.id]:22s} {c.text}")
    print(f"\nWritten to {_shown(out)} and {_shown(numbers)}")
    return 0
